<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Token Generator','description'=>'Generate cryptographically random token strings using Web Crypto.','url'=>'https://smarttoolz.in/tools/password-token-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Password Token Generator</h1><p>Generate secure random token strings.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Length<input id="n" type="number" min="8" max="256" value="32"></label><button id="go" class="tool-btn">Generate Token</button><textarea id="o" rows="5" readonly></textarea></div></section></main><script>go.onclick=()=>{let n=Math.min(256,Math.max(8,+n.value||32)),a=new Uint8Array(n);crypto.getRandomValues(a);o.value=btoa(String.fromCharCode(...a)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','').slice(0,n)}</script><?php smarttoolz_tool_page_end(); ?>